<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { formatDateTime, statusLabel } from '../../utils/display'
import { dataSourceApi, type DataSourceView } from '../../api/platform'
import {
  flinkApi, integrationApi, realtimeApi, releaseApi,
  type FlinkEnvironment, type RealtimeCheckpointRow, type RealtimeColumnOption, type RealtimeEventRow,
  type RealtimeExecution, type RealtimeJob, type RealtimeManagementRow, type RealtimePreCheckItem,
  type RealtimeSchemaChangeRow, type RealtimeTableOption, type RealtimeValidationRow
} from '../../api/domain'

const loading=ref(false), saving=ref(false), prechecking=ref(false)
const rows=ref<RealtimeManagementRow[]>([]), sources=ref<DataSourceView[]>([]), envs=ref<FlinkEnvironment[]>([])
const editorVisible=ref(false), editorStep=ref(0), editing=ref<RealtimeJob|null>(null), advancedRuntime=ref(false)
const sourceDatabases=ref<Array<{name:string}>>([]), targetDatabases=ref<Array<{name:string}>>([])
const sourceTables=ref<RealtimeTableOption[]>([]), sourceTableKeyword=ref(''), selectedTables=ref<string[]>([])
const fieldColumns=ref<RealtimeColumnOption[]>([]), fieldTable=ref(''), targetTables=reactive<Record<string,string>>({})
const precheckItems=ref<RealtimePreCheckItem[]>([]), yamlPreview=ref('')
const detailVisible=ref(false), detailLoading=ref(false), detailTab=ref('overview'), detailJob=ref<RealtimeJob|null>(null)
const detailRuntime=ref<any>(null), detailMetrics=ref<any>(null), detailLogs=ref<any>(null)
const executions=ref<RealtimeExecution[]>([]), events=ref<RealtimeEventRow[]>([]), checkpointRows=ref<RealtimeCheckpointRow[]>([])
const schemaChanges=ref<RealtimeSchemaChangeRow[]>([]), validationRows=ref<RealtimeValidationRow[]>([])
let detailTimer:ReturnType<typeof setInterval>|null=null

const form=reactive<any>({
  name:'', description:'', sourceDataSourceId:undefined, sourceDatabase:'', syncScope:'MULTI_TABLE',
  startupMode:'initial', timestampMillis:undefined, binlogFile:'', binlogPosition:0, gtid:'',
  syncSchema:true, addColumnPolicy:'AUTO', typeChangePolicy:'MANUAL', renameColumnPolicy:'MANUAL',
  dropColumnPolicy:'KEEP_TARGET', newTablePolicy:'MANUAL', dropTablePolicy:'KEEP_TARGET', deletePolicy:'SYNC_DELETE', dataFilter:'',
  sinkDataSourceId:undefined, sinkDatabase:'ods', targetStrategy:'AUTO_CREATE', targetPrefix:'', targetSuffix:'', regexPattern:'', regexReplacement:'',
  bucketCount:0, replicationNum:1, runtimeEnvironmentId:undefined, parallelism:1,
  checkpointEnabled:true, checkpointIntervalSec:60, checkpointTimeoutSec:600, checkpointTolerance:3, externalizedCheckpoint:'RETAIN',
  restartStrategy:'FIXED_DELAY', restartAttempts:3, restartDelaySec:10, jmMemory:'1024m', tmMemory:'2048m', taskSlots:2,
  checkpointMinPauseSec:5, maxConcurrentCheckpoints:1, stateBackend:'rocksdb', checkpointStorage:'', savepointPath:'', advancedParams:''
})

const mysqlSources=computed(()=>sources.value.filter(s=>s.type==='MYSQL'))
const starrocksSources=computed(()=>sources.value.filter(s=>s.type==='STARROCKS'))
const filteredTables=computed(()=>{const q=sourceTableKeyword.value.trim().toLowerCase();return q?sourceTables.value.filter(t=>`${t.name} ${t.comment||''}`.toLowerCase().includes(q)):sourceTables.value})
const selectedTableOptions=computed(()=>selectedTables.value.map(name=>sourceTables.value.find(t=>t.name===name)).filter(Boolean) as RealtimeTableOption[])
const activeDetailRow=computed(()=>rows.value.find(r=>r.id===detailJob.value?.id))

function scopeLabel(v?:string){return v==='SINGLE_TABLE'?'单表':v==='FULL_DATABASE'?'整库':'多表'}
function releaseLabel(v?:string){return statusLabel(v)}
function fmtCount(v?:number){return v==null?'—':new Intl.NumberFormat('zh-CN').format(v)}
function fmtBytes(v?:number){if(v==null)return '—';if(v>=1024**3)return `${(v/1024**3).toFixed(2)} GB`;if(v>=1024**2)return `${(v/1024**2).toFixed(1)} MB`;if(v>=1024)return `${(v/1024).toFixed(1)} KB`;return `${v} B`}
function fmtDuration(v?:number){if(v==null)return '—';if(v<1000)return `${v} ms`;if(v<60000)return `${(v/1000).toFixed(1)} s`;return `${(v/60000).toFixed(1)} min`}
function sourceName(id?:string|number){return sources.value.find(s=>String(s.id)===String(id))?.name||'未配置'}
function envName(id?:number){return envs.value.find(e=>e.id===id)?.name||'未配置'}
function jobIdShort(v?:string){return v?v.length>14?`${v.slice(0,12)}…`:v:'—'}
function cdcTone(t:RealtimeTableOption){return t.primaryKey?'ok':'warn'}
function startupLabel(v:string){return ({initial:'全量 + 增量','latest-offset':'仅增量',timestamp:'指定时间开始','specific-offset':'指定 Binlog 位点'} as any)[v]||v}
function deleteLabel(v:string){return ({SYNC_DELETE:'同步删除',IGNORE_DELETE:'忽略删除',LOGICAL_DELETE:'转换为逻辑删除'} as any)[v]||v}
function schemaBehavior(){if(!form.syncSchema)return 'IGNORE';if([form.typeChangePolicy,form.renameColumnPolicy].includes('BLOCK')||form.dropColumnPolicy==='BLOCK')return 'EXCEPTION';if(form.addColumnPolicy==='AUTO')return 'TRY_EVOLVE';return 'EXCEPTION'}

function buildSpec(){
  const specificOffset=form.gtid?.trim()?{gtid:form.gtid.trim()}:{file:form.binlogFile?.trim(),pos:Number(form.binlogPosition||0)}
  return {
    editorMode:'GUIDE',name:form.name,sourceDataSourceId:form.sourceDataSourceId,sinkDataSourceId:form.sinkDataSourceId,
    sourceDatabase:form.sourceDatabase,sinkDatabase:form.sinkDatabase,syncScope:form.syncScope,
    tables:selectedTables.value.map(t=>({sourceTable:t,targetTable:targetTables[t]||t})),
    startupMode:form.startupMode,timestampMillis:form.timestampMillis,specificOffset,
    schemaEvolution:schemaBehavior(),schemaPolicies:{syncSchema:form.syncSchema,addColumn:form.addColumnPolicy,typeChange:form.typeChangePolicy,renameColumn:form.renameColumnPolicy,dropColumn:form.dropColumnPolicy,newTable:form.newTablePolicy,dropTable:form.dropTablePolicy},
    deletePolicy:form.deletePolicy,dataFilter:form.dataFilter,
    targetStrategy:form.targetStrategy,targetNaming:{prefix:form.targetPrefix,suffix:form.targetSuffix,regexPattern:form.regexPattern,regexReplacement:form.regexReplacement},
    starrocks:{bucketCount:form.bucketCount,replicationNum:form.replicationNum},parallelism:form.parallelism,
    checkpoint:{enabled:form.checkpointEnabled,intervalSec:form.checkpointIntervalSec,timeoutSec:form.checkpointTimeoutSec,tolerableFailures:form.checkpointTolerance,externalized:form.externalizedCheckpoint,minPauseSec:form.checkpointMinPauseSec,maxConcurrent:form.maxConcurrentCheckpoints,storage:form.checkpointStorage},
    restart:{strategy:form.restartStrategy,attempts:form.restartAttempts,delaySec:form.restartDelaySec},
    resources:{jobManagerMemory:form.jmMemory,taskManagerMemory:form.tmMemory,taskSlots:form.taskSlots,stateBackend:form.stateBackend,savepointPath:form.savepointPath,advancedParams:form.advancedParams},
    chunkSize:8096,fetchSize:1024,heartbeatMs:30000,sink:{maxBytes:67108864,flushIntervalMs:2000}
  }
}
function payload(){return {name:form.name.trim(),description:form.description?.trim(),runtimeEnvironmentId:form.runtimeEnvironmentId,spec:buildSpec()}}

async function load(){loading.value=true;try{[rows.value,sources.value,envs.value]=await Promise.all([realtimeApi.management(),dataSourceApi.list(),flinkApi.list()])}catch(e){ElMessage.error(e instanceof Error?e.message:'实时任务加载失败')}finally{loading.value=false}}
function resetForm(){editing.value=null;editorStep.value=0;precheckItems.value=[];yamlPreview.value='';sourceTables.value=[];selectedTables.value=[];fieldColumns.value=[];fieldTable.value='';sourceTableKeyword.value='';for(const k of Object.keys(targetTables))delete targetTables[k];Object.assign(form,{name:'',description:'',sourceDataSourceId:mysqlSources.value[0]?.id,sourceDatabase:mysqlSources.value[0]?.databaseName||'',syncScope:'MULTI_TABLE',startupMode:'initial',timestampMillis:undefined,binlogFile:'',binlogPosition:0,gtid:'',syncSchema:true,addColumnPolicy:'AUTO',typeChangePolicy:'MANUAL',renameColumnPolicy:'MANUAL',dropColumnPolicy:'KEEP_TARGET',newTablePolicy:'MANUAL',dropTablePolicy:'KEEP_TARGET',deletePolicy:'SYNC_DELETE',dataFilter:'',sinkDataSourceId:starrocksSources.value[0]?.id,sinkDatabase:starrocksSources.value[0]?.databaseName||'ods',targetStrategy:'AUTO_CREATE',targetPrefix:'',targetSuffix:'',regexPattern:'',regexReplacement:'',bucketCount:0,replicationNum:1,runtimeEnvironmentId:envs.value.find(e=>e.defaultEnvironment)?.id||envs.value.find(e=>e.enabled)?.id,parallelism:1,checkpointEnabled:true,checkpointIntervalSec:60,checkpointTimeoutSec:600,checkpointTolerance:3,externalizedCheckpoint:'RETAIN',restartStrategy:'FIXED_DELAY',restartAttempts:3,restartDelaySec:10,jmMemory:'1024m',tmMemory:'2048m',taskSlots:2,checkpointMinPauseSec:5,maxConcurrentCheckpoints:1,stateBackend:'rocksdb',checkpointStorage:'',savepointPath:'',advancedParams:''})}
async function openCreate(){resetForm();editorVisible.value=true;await Promise.all([loadSourceDatabases(),loadTargetDatabases()]);if(form.sourceDatabase)await loadSourceTables()}
async function openEdit(row:RealtimeManagementRow){resetForm();const job=await realtimeApi.get(row.id);editing.value=job;const s:any=job.spec||{};Object.assign(form,{name:job.name,description:job.description||'',runtimeEnvironmentId:job.runtimeEnvironmentId,sourceDataSourceId:s.sourceDataSourceId,sourceDatabase:s.sourceDatabase||'',syncScope:s.syncScope||((s.tables?.length||0)===1?'SINGLE_TABLE':'MULTI_TABLE'),startupMode:s.startupMode||'initial',timestampMillis:s.timestampMillis,binlogFile:s.specificOffset?.file||'',binlogPosition:s.specificOffset?.pos||0,gtid:s.specificOffset?.gtid||'',syncSchema:s.schemaPolicies?.syncSchema!==false,addColumnPolicy:s.schemaPolicies?.addColumn||'AUTO',typeChangePolicy:s.schemaPolicies?.typeChange||'MANUAL',renameColumnPolicy:s.schemaPolicies?.renameColumn||'MANUAL',dropColumnPolicy:s.schemaPolicies?.dropColumn||'KEEP_TARGET',newTablePolicy:s.schemaPolicies?.newTable||'MANUAL',dropTablePolicy:s.schemaPolicies?.dropTable||'KEEP_TARGET',deletePolicy:s.deletePolicy||'SYNC_DELETE',dataFilter:s.dataFilter||'',sinkDataSourceId:s.sinkDataSourceId,sinkDatabase:s.sinkDatabase||'ods',targetStrategy:s.targetStrategy||'AUTO_CREATE',targetPrefix:s.targetNaming?.prefix||'',targetSuffix:s.targetNaming?.suffix||'',regexPattern:s.targetNaming?.regexPattern||'',regexReplacement:s.targetNaming?.regexReplacement||'',parallelism:s.parallelism||1,bucketCount:s.starrocks?.bucketCount||0,replicationNum:s.starrocks?.replicationNum||1,checkpointEnabled:s.checkpoint?.enabled!==false,checkpointIntervalSec:s.checkpoint?.intervalSec||60,checkpointTimeoutSec:s.checkpoint?.timeoutSec||600,checkpointTolerance:s.checkpoint?.tolerableFailures??3,externalizedCheckpoint:s.checkpoint?.externalized||'RETAIN',checkpointMinPauseSec:s.checkpoint?.minPauseSec||5,maxConcurrentCheckpoints:s.checkpoint?.maxConcurrent||1,checkpointStorage:s.checkpoint?.storage||'',restartStrategy:s.restart?.strategy||'FIXED_DELAY',restartAttempts:s.restart?.attempts||3,restartDelaySec:s.restart?.delaySec||10,jmMemory:s.resources?.jobManagerMemory||'1024m',tmMemory:s.resources?.taskManagerMemory||'2048m',taskSlots:s.resources?.taskSlots||2,stateBackend:s.resources?.stateBackend||'rocksdb',savepointPath:s.resources?.savepointPath||'',advancedParams:s.resources?.advancedParams||''});selectedTables.value=(s.tables||[]).map((t:any)=>t.sourceTable);for(const t of s.tables||[])targetTables[t.sourceTable]=t.targetTable||t.sourceTable;editorVisible.value=true;await Promise.all([loadSourceDatabases(),loadTargetDatabases()]);if(form.sourceDatabase)await loadSourceTables();await loadFieldMapping()}

async function loadSourceDatabases(){if(!form.sourceDataSourceId)return;try{sourceDatabases.value=await integrationApi.sourceDatabases(form.sourceDataSourceId)}catch(e){ElMessage.error(e instanceof Error?e.message:'读取源数据库失败')}}
async function loadTargetDatabases(){if(!form.sinkDataSourceId)return;try{targetDatabases.value=await integrationApi.targetDatabases(form.sinkDataSourceId)}catch(e){ElMessage.error(e instanceof Error?e.message:'读取目标数据库失败')}}
async function loadSourceTables(){if(!form.sourceDataSourceId||!form.sourceDatabase)return;try{sourceTables.value=await realtimeApi.tables(form.sourceDataSourceId,form.sourceDatabase);if(form.syncScope==='FULL_DATABASE'){selectedTables.value=sourceTables.value.map(t=>t.name);ensureTargetNames()}}catch(e){ElMessage.error(e instanceof Error?e.message:'读取表失败')}}
async function sourceChanged(){form.sourceDatabase='';selectedTables.value=[];sourceTables.value=[];await loadSourceDatabases()}
async function sourceDatabaseChanged(){selectedTables.value=[];for(const k of Object.keys(targetTables))delete targetTables[k];await loadSourceTables()}
async function sinkChanged(){form.sinkDatabase='';await loadTargetDatabases()}
function scopeChanged(){if(form.syncScope==='SINGLE_TABLE'&&selectedTables.value.length>1)selectedTables.value=selectedTables.value.slice(0,1);if(form.syncScope==='FULL_DATABASE')selectedTables.value=sourceTables.value.map(t=>t.name);ensureTargetNames();void loadFieldMapping()}
function toggleTable(name:string){if(form.syncScope==='FULL_DATABASE')return;if(form.syncScope==='SINGLE_TABLE')selectedTables.value=selectedTables.value.includes(name)?[]:[name];else selectedTables.value=selectedTables.value.includes(name)?selectedTables.value.filter(x=>x!==name):[...selectedTables.value,name];ensureTargetNames();void loadFieldMapping()}
function selectAllCdc(){if(form.syncScope==='SINGLE_TABLE')return;selectedTables.value=sourceTables.value.filter(t=>t.primaryKey).map(t=>t.name);ensureTargetNames();void loadFieldMapping()}
function ensureTargetNames(){for(const table of selectedTables.value){if(!targetTables[table])targetTables[table]=mappedName(table)}}
function mappedName(table:string){let name=table;if(form.regexPattern){try{name=name.replace(new RegExp(form.regexPattern,'g'),form.regexReplacement||'')}catch{}}return `${form.targetPrefix||''}${name}${form.targetSuffix||''}`}
function applyNaming(){for(const t of selectedTables.value)targetTables[t]=mappedName(t)}
async function loadFieldMapping(table?:string){const t=table||selectedTables.value[0];fieldTable.value=t||'';if(!t||!form.sourceDataSourceId||!form.sourceDatabase){fieldColumns.value=[];return}try{fieldColumns.value=await realtimeApi.columns(form.sourceDataSourceId,form.sourceDatabase,t)}catch(e){fieldColumns.value=[];ElMessage.error(e instanceof Error?e.message:'读取字段失败')}}

function checkStep(step:number){if(step===0){if(!form.name.trim())return '请输入任务名称';if(!form.sourceDataSourceId)return '请选择 MySQL 数据源';if(!form.sourceDatabase)return '请选择 Database';if(!selectedTables.value.length)return '请选择至少一张同步表';const bad=selectedTableOptions.value.filter(t=>!t.primaryKey);if(bad.length)return `实时同步要求主键，以下表不可直接创建：${bad.map(t=>t.name).join('、')}`}if(step===2){if(!form.sinkDataSourceId)return '请选择 StarRocks 数据源';if(!form.sinkDatabase)return '请选择目标 Database';ensureTargetNames()}if(step===3&&!form.runtimeEnvironmentId)return '请选择 Flink 环境';return ''}
async function nextStep(){const m=checkStep(editorStep.value);if(m)return ElMessage.warning(m);if(editorStep.value<3){editorStep.value++;if(editorStep.value===1)await loadFieldMapping();return}if(editorStep.value===3){editorStep.value=4;await runPrecheck()}}
function prevStep(){if(editorStep.value>0)editorStep.value--}
async function runPrecheck(){const m=[0,2,3].map(checkStep).find(Boolean);if(m)return ElMessage.warning(m);prechecking.value=true;try{const v=editing.value?await realtimeApi.validate(editing.value.id):await realtimeApi.previewValidate(payload());precheckItems.value=v.items||[];yamlPreview.value=v.yamlPreview||'';v.valid?ElMessage.success(v.message):ElMessage.warning(v.message)}catch(e){ElMessage.error(e instanceof Error?e.message:'创建前检查失败')}finally{prechecking.value=false}}
async function finalSave(){if(precheckItems.value.some(x=>x.blocking))return ElMessage.warning('存在阻断项，请修复后再创建');saving.value=true;try{if(editing.value)await realtimeApi.draft(editing.value.id,payload());else await realtimeApi.create(payload());ElMessage.success(editing.value?'实时任务修改已保存，需重新发布后才会应用到运行版本':'实时任务已创建，请发布后再单独启动');editorVisible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'保存实时任务失败')}finally{saving.value=false}}

async function start(row:RealtimeManagementRow){try{await realtimeApi.start(row.id);ElMessage.success('实时任务已启动');await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'启动失败')}}
async function stop(row:RealtimeManagementRow){try{await ElMessageBox.confirm(`确认停止“${row.name}”？`,'停止实时任务',{type:'warning',confirmButtonText:'停止',cancelButtonText:'取消'});await realtimeApi.stop(row.id);ElMessage.success('停止请求已完成');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'停止失败')}}
async function restart(row:RealtimeManagementRow){try{await ElMessageBox.confirm(`确认重启“${row.name}”？当前 Flink Job 会先停止再重新提交。`,'重启实时任务',{type:'warning',confirmButtonText:'重启',cancelButtonText:'取消'});await realtimeApi.restart(row.id);ElMessage.success('任务已重启');await load();if(detailJob.value?.id===row.id)await loadDetailRuntime()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'重启失败')}}
async function publishRow(row:RealtimeManagementRow){try{const job=await realtimeApi.get(row.id);const v=await realtimeApi.validate(row.id);if(!v.valid)return ElMessage.error(v.message);await releaseApi.request({resourceType:'REALTIME',resourceId:job.id,resourceName:job.name,requestedVersion:job.definitionVersion});ElMessage.success('发布请求已处理');await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'发布失败')}}
async function copyTask(row:RealtimeManagementRow){try{const job=await realtimeApi.get(row.id);const copy=await realtimeApi.create({name:`${job.name}-副本`,description:job.description,runtimeEnvironmentId:job.runtimeEnvironmentId,spec:{...job.spec,name:`${job.name}-副本`}});ElMessage.success(`已复制为草稿：${copy.name}`);await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'复制失败')}}

async function openDetail(row:RealtimeManagementRow,tab='overview'){detailVisible.value=true;detailTab.value=tab;detailLoading.value=true;try{detailJob.value=await realtimeApi.get(row.id);await Promise.all([loadDetailRuntime(),loadDetailHistory(),loadDetailTab(tab)])}finally{detailLoading.value=false}startDetailPoll()}
async function loadDetailRuntime(){if(!detailJob.value)return;try{detailRuntime.value=await realtimeApi.runtime(detailJob.value.id)}catch{}}
async function loadDetailHistory(){if(!detailJob.value)return;const id=detailJob.value.id;const all=await Promise.allSettled([realtimeApi.executions(id),realtimeApi.events(id),realtimeApi.checkpointHistory(id),realtimeApi.schemaChanges(id),realtimeApi.validationResults(id)]);if(all[0].status==='fulfilled')executions.value=all[0].value;if(all[1].status==='fulfilled')events.value=all[1].value;if(all[2].status==='fulfilled')checkpointRows.value=all[2].value;if(all[3].status==='fulfilled')schemaChanges.value=all[3].value;if(all[4].status==='fulfilled')validationRows.value=all[4].value}
async function loadDetailTab(tab:string){if(!detailJob.value)return;const id=detailJob.value.id;if(tab==='monitor'){try{detailMetrics.value=await realtimeApi.metrics(id)}catch{detailMetrics.value=null}}if(tab==='checkpoint'){try{await realtimeApi.checkpoints(id);checkpointRows.value=await realtimeApi.checkpointHistory(id)}catch{}}if(tab==='logs'){try{detailLogs.value=await realtimeApi.logs(id)}catch(e){detailLogs.value={message:e instanceof Error?e.message:'暂时无法读取 Flink 日志'}}}}
function detailTabChanged(tab:any){void loadDetailTab(String(tab))}
function closeDetail(){stopDetailPoll();detailVisible.value=false}
function startDetailPoll(){stopDetailPoll();detailTimer=setInterval(async()=>{if(detailVisible.value&&detailJob.value&&['RUNNING','STARTING'].includes(detailRuntime.value?.job?.observedState||'')){await loadDetailRuntime();if(detailTab.value==='monitor')await loadDetailTab('monitor')}},4000)}
function stopDetailPoll(){if(detailTimer){clearInterval(detailTimer);detailTimer=null}}
async function runDataValidation(){if(!detailJob.value)return;try{validationRows.value=await realtimeApi.dataValidation(detailJob.value.id);ElMessage.success('数据校验完成')}catch(e){ElMessage.error(e instanceof Error?e.message:'数据校验失败')}}
function metricValue(id:string){const arr=detailMetrics.value?.job;if(Array.isArray(arr)){const item=arr.find((x:any)=>x.id===id);if(item?.value!=null)return Number(item.value)}return undefined}
function vertexMetric(key:string){const vertices=detailMetrics.value?.vertices;if(!Array.isArray(vertices))return undefined;let sum=0,found=false;for(const v of vertices){const arr=v.metrics;if(!Array.isArray(arr))continue;const item=arr.find((x:any)=>x.id===key);if(item?.value!=null){sum+=Number(item.value);found=true}}return found?sum:undefined}
function taskManagerCount(){const t=detailMetrics.value?.taskmanagers?.taskmanagers;return Array.isArray(t)?t.length:undefined}
async function scanSchema(){if(!detailJob.value)return;try{schemaChanges.value=await realtimeApi.scanSchemaChanges(detailJob.value.id);ElMessage.success('Schema 变更检测完成')}catch(e){ElMessage.error(e instanceof Error?e.message:'Schema 检测失败')}}
function logText(){return detailLogs.value?JSON.stringify(detailLogs.value,null,2):'暂无 Flink 异常/日志信息'}
onMounted(load);onBeforeUnmount(stopDetailPoll)
</script>

<template>
<div class="ds-page ds-integration-page realtime-page">
  <PageHeader title="实时同步" subtitle="MySQL CDC → 独立 Flink CDC → StarRocks。创建体验面向数据开发，运行阶段面向生产运维。">
    <template #actions><el-button type="primary" @click="openCreate">+ 新建实时同步任务</el-button></template>
  </PageHeader>

  <div class="ds-card task-card">
    <div class="ds-toolbar"><strong>实时任务</strong><span class="count-tip">共 {{ rows.length }} 个任务</span><div class="ds-spacer"/><el-button @click="load" :loading="loading">刷新</el-button></div>
    <el-table :data="rows" v-loading="loading" class="realtime-table" @row-dblclick="(r:any)=>openDetail(r)">
      <el-table-column label="任务名称" min-width="175" show-overflow-tooltip><template #default="s"><button class="name-link" @click="openDetail(s.row)">{{s.row.name}}</button><div class="minor">{{s.row.owner||'—'}}</div></template></el-table-column>
      <el-table-column label="来源" min-width="150"><template #default="s"><strong>{{sourceName(s.row.sourceDataSourceId)}}</strong><div class="minor">{{s.row.sourceDatabase||'—'}}</div></template></el-table-column>
      <el-table-column label="目标" min-width="150"><template #default="s"><strong>{{sourceName(s.row.sinkDataSourceId)}}</strong><div class="minor">{{s.row.sinkDatabase||'—'}}</div></template></el-table-column>
      <el-table-column label="同步范围" width="100"><template #default="s">{{scopeLabel(s.row.syncScope)}}<div class="minor">{{s.row.tableCount}} 张表</div></template></el-table-column>
      <el-table-column label="发布状态" width="115"><template #default="s"><StatusBadge :status="s.row.releaseState" :label="releaseLabel(s.row.releaseState)"/></template></el-table-column>
      <el-table-column label="运行状态" width="110"><template #default="s"><StatusBadge :status="s.row.observedState"/></template></el-table-column>
      <el-table-column label="Flink 环境" min-width="135"><template #default="s">{{s.row.environmentName||'未配置'}}</template></el-table-column>
      <el-table-column label="JobId" min-width="135" show-overflow-tooltip><template #default="s"><span class="mono">{{jobIdShort(s.row.engineJobId)}}</span></template></el-table-column>
      <el-table-column label="延迟" width="90"><template #default="s">{{s.row.lagMs==null?'未采集':`${(s.row.lagMs/1000).toFixed(1)}s`}}</template></el-table-column>
      <el-table-column label="Checkpoint" width="115"><template #default="s"><StatusBadge :status="s.row.checkpointStatus" :label="s.row.checkpointStatus==='COMPLETED'?'正常':'未采集'"/></template></el-table-column>
      <el-table-column label="最后更新时间" min-width="165"><template #default="s">{{formatDateTime(s.row.updatedAt)}}</template></el-table-column>
      <el-table-column label="负责人" width="95"><template #default="s">{{s.row.owner||'—'}}</template></el-table-column>
      <el-table-column label="操作" width="270" fixed="right"><template #default="s"><el-button link type="primary" @click="openDetail(s.row)">详情</el-button><el-button v-if="s.row.releaseState!=='PUBLISHED'" link type="primary" @click="publishRow(s.row)">发布</el-button><el-button v-else-if="s.row.observedState==='RUNNING'" link type="warning" @click="stop(s.row)">停止</el-button><el-button v-else link type="success" @click="start(s.row)">启动</el-button><el-button v-if="s.row.releaseState==='PUBLISHED'&&s.row.observedState==='RUNNING'" link type="primary" @click="restart(s.row)">重启</el-button><el-button link @click="openDetail(s.row,'logs')">日志</el-button><el-dropdown trigger="click"><el-button link>更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="openEdit(s.row)">编辑</el-dropdown-item><el-dropdown-item v-if="s.row.releaseState==='PUBLISHED'" @click="publishRow(s.row)">重新发布</el-dropdown-item><el-dropdown-item @click="copyTask(s.row)">复制</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column>
    </el-table>
  </div>

  <el-drawer v-model="editorVisible" size="72%" destroy-on-close :close-on-click-modal="false" class="wizard-drawer">
    <template #header><div class="drawer-head"><div><h3>{{editing?'编辑实时同步任务':'新建实时同步任务'}}</h3><p>业务配置由平台转换为 Flink CDC Pipeline，普通用户无需填写 Connector / Debezium 底层参数。</p></div></div></template>
    <div class="wizard-shell">
      <el-steps :active="editorStep" align-center finish-status="success" class="wizard-steps"><el-step title="选择数据"/><el-step title="同步配置"/><el-step title="目标配置"/><el-step title="运行配置"/><el-step title="确认创建"/></el-steps>

      <section v-if="editorStep===0" class="wizard-section">
        <div class="section-head"><div><h4>选择数据</h4><p>先选择需要实时同步的 MySQL 数据，不暴露 Flink 参数。</p></div></div>
        <el-form label-position="top"><div class="form-grid"><el-form-item label="任务名称"><el-input v-model="form.name" placeholder="例如 用户订单实时同步"/></el-form-item><el-form-item label="任务描述"><el-input v-model="form.description" placeholder="可选"/></el-form-item><el-form-item label="源数据源"><el-select v-model="form.sourceDataSourceId" style="width:100%" @change="sourceChanged"><el-option v-for="s in mysqlSources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="Database"><el-select v-model="form.sourceDatabase" filterable style="width:100%" @change="sourceDatabaseChanged"><el-option v-for="d in sourceDatabases" :key="d.name" :label="d.name" :value="d.name"/></el-select></el-form-item></div><el-form-item label="同步范围"><el-radio-group v-model="form.syncScope" @change="scopeChanged"><el-radio-button value="SINGLE_TABLE">单表</el-radio-button><el-radio-button value="MULTI_TABLE">多表</el-radio-button><el-radio-button value="FULL_DATABASE">整库</el-radio-button></el-radio-group></el-form-item></el-form>
        <div class="table-picker"><div class="picker-head"><el-input v-model="sourceTableKeyword" clearable placeholder="搜索表名 / 注释" style="width:280px"/><div class="ds-spacer"/><el-button v-if="form.syncScope!=='SINGLE_TABLE'" @click="selectAllCdc">选择全部支持 CDC 的表</el-button><span>已选 {{selectedTables.length}} 张</span></div><div class="table-list"><button v-for="t in filteredTables" :key="t.name" type="button" :class="['table-option',{selected:selectedTables.includes(t.name),disabled:form.syncScope==='FULL_DATABASE'}]" @click="toggleTable(t.name)"><span class="check">{{selectedTables.includes(t.name)?'✓':''}}</span><span class="table-copy"><strong>{{t.name}}</strong><small>{{t.comment||'暂无注释'}}</small></span><span class="pk">{{t.primaryKey?'PK':'无主键'}}</span><span class="rows">约 {{fmtCount(t.estimatedRows)}} 行</span><span :class="['cdc',cdcTone(t)]">{{t.cdcStatus}}</span></button></div></div>
      </section>

      <section v-else-if="editorStep===1" class="wizard-section">
        <div class="section-head"><div><h4>同步配置</h4><p>配置业务同步规则；TINYINT(1)、UNSIGNED、DATETIME/TIMESTAMP 等类型策略由平台自动处理。</p></div></div>
        <div class="form-card"><h5>启动模式</h5><el-radio-group v-model="form.startupMode"><el-radio value="initial">全量 + 增量</el-radio><el-radio value="latest-offset">仅增量</el-radio><el-radio value="timestamp">指定时间开始</el-radio><el-radio value="specific-offset">指定 Binlog 位点</el-radio></el-radio-group><div v-if="form.startupMode==='timestamp'" class="inline-config"><el-date-picker v-model="form.timestampMillis" type="datetime" value-format="x" placeholder="选择开始时间"/></div><div v-if="form.startupMode==='specific-offset'" class="form-grid inline-config"><el-input v-model="form.binlogFile" placeholder="Binlog File，例如 mysql-bin.000123"/><el-input-number v-model="form.binlogPosition" :min="0" style="width:100%"/><el-input v-model="form.gtid" placeholder="GTID（填写后优先使用 GTID）"/></div></div>
        <div class="form-card"><div class="card-head"><h5>表结构同步 / Schema Evolution</h5><el-switch v-model="form.syncSchema" active-text="同步结构变化" inactive-text="忽略结构变化"/></div><div class="policy-grid" v-if="form.syncSchema"><label>新增字段<el-select v-model="form.addColumnPolicy"><el-option label="自动同步" value="AUTO"/><el-option label="阻塞任务" value="BLOCK"/><el-option label="忽略" value="IGNORE"/></el-select></label><label>字段类型变化<el-select v-model="form.typeChangePolicy"><el-option label="人工确认" value="MANUAL"/><el-option label="自动兼容" value="AUTO"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label><label>字段重命名<el-select v-model="form.renameColumnPolicy"><el-option label="人工确认" value="MANUAL"/><el-option label="自动同步" value="AUTO"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label><label>删除字段<el-select v-model="form.dropColumnPolicy"><el-option label="保留目标字段" value="KEEP_TARGET"/><el-option label="自动删除" value="AUTO"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label><label>新增表<el-select v-model="form.newTablePolicy"><el-option label="人工确认" value="MANUAL"/><el-option label="自动同步" value="AUTO"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label><label>删除表<el-select v-model="form.dropTablePolicy"><el-option label="保留目标表" value="KEEP_TARGET"/><el-option label="人工确认" value="MANUAL"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label></div></div>
        <div class="form-card"><h5>数据过滤</h5><el-input v-model="form.dataFilter" placeholder="可选，例如 status = 1 AND created_at >= '2026-01-01'"/><div class="rule-note">过滤条件直接生成到 Flink CDC Transform。多表同步时请确保过滤字段在所有选中表中存在。</div></div>
        <div class="form-card"><h5>DELETE 同步</h5><el-radio-group v-model="form.deletePolicy"><el-radio value="SYNC_DELETE">同步删除</el-radio><el-radio value="IGNORE_DELETE">忽略删除</el-radio><el-radio value="LOGICAL_DELETE">转换为逻辑删除</el-radio></el-radio-group><div class="rule-note">默认“同步删除”。源表无主键时平台会阻断创建，避免 UPDATE / DELETE 静默错误。</div></div>
        <div class="form-card"><div class="card-head"><h5>字段映射</h5><el-select v-model="fieldTable" style="width:240px" @change="(v:any)=>loadFieldMapping(v)"><el-option v-for="t in selectedTables" :key="t" :label="t" :value="t"/></el-select></div><el-table :data="fieldColumns" size="small"><el-table-column prop="name" label="MySQL 字段" min-width="150"/><el-table-column prop="mysqlType" label="类型" min-width="170"/><el-table-column label="主键" width="70"><template #default="s">{{s.row.primaryKey?'PK':'—'}}</template></el-table-column><el-table-column label="可空" width="70"><template #default="s">{{s.row.nullable?'是':'否'}}</template></el-table-column><el-table-column prop="starRocksType" label="StarRocks 类型" min-width="170"/><el-table-column label="目标字段" min-width="140"><template #default="s">{{s.row.name}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><span :class="s.row.starRocksType==='不兼容'?'mapping-error':'mapping-ok'">{{s.row.starRocksType==='不兼容'?'需处理':'可同步'}}</span></template></el-table-column></el-table></div>
      </section>

      <section v-else-if="editorStep===2" class="wizard-section">
        <div class="section-head"><div><h4>目标配置</h4><p>配置 StarRocks 目标库、建表策略和多表映射。</p></div></div>
        <el-form label-position="top"><div class="form-grid"><el-form-item label="目标数据源"><el-select v-model="form.sinkDataSourceId" style="width:100%" @change="sinkChanged"><el-option v-for="s in starrocksSources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="Database"><el-select v-model="form.sinkDatabase" filterable style="width:100%"><el-option v-for="d in targetDatabases" :key="d.name" :label="d.name" :value="d.name"/></el-select></el-form-item></div><el-form-item label="目标表策略"><el-radio-group v-model="form.targetStrategy"><el-radio value="AUTO_CREATE">自动创建</el-radio><el-radio value="USE_EXISTING">使用已有表</el-radio><el-radio value="MANUAL">手动映射</el-radio></el-radio-group></el-form-item></el-form>
        <div class="form-card"><h5>表名映射</h5><div class="mapping-tools"><el-input v-model="form.targetPrefix" placeholder="前缀，例如 ods_" @change="applyNaming"/><el-input v-model="form.targetSuffix" placeholder="后缀" @change="applyNaming"/><el-input v-model="form.regexPattern" placeholder="正则匹配（可选）" @change="applyNaming"/><el-input v-model="form.regexReplacement" placeholder="正则替换" @change="applyNaming"/><el-button @click="applyNaming">应用</el-button></div><el-table :data="selectedTables" size="small"><el-table-column label="源表" min-width="180"><template #default="s">{{form.sourceDatabase}}.{{s.row}}</template></el-table-column><el-table-column label="目标表" min-width="230"><template #default="s"><el-input v-model="targetTables[s.row]"/></template></el-table-column><el-table-column label="建表状态" width="120"><template #default>平台预检</template></el-table-column><el-table-column label="主键" width="130"><template #default="s">{{sourceTables.find(t=>t.name===s.row)?.primaryKey?'沿用 MySQL PK':'缺失'}}</template></el-table-column><el-table-column label="模型" width="120"><template #default>Primary Key</template></el-table-column></el-table></div>
        <div class="form-card"><h5>StarRocks 建表</h5><div class="form-grid"><label class="field-label">Bucket 数量<el-input-number v-model="form.bucketCount" :min="0" style="width:100%"/><small>0 = 平台自动推导</small></label><label class="field-label">Replication<el-input-number v-model="form.replicationNum" :min="1" :max="3" style="width:100%"/></label></div></div>
      </section>

      <section v-else-if="editorStep===3" class="wizard-section">
        <div class="section-head"><div><h4>运行配置</h4><p>前 3 步只描述数据同步；这里才配置 Flink 运行参数。</p></div></div>
        <div class="form-card"><h5>基础配置</h5><div class="form-grid"><label class="field-label">Flink 环境<el-select v-model="form.runtimeEnvironmentId" style="width:100%"><el-option v-for="e in envs.filter(x=>x.enabled)" :key="e.id" :label="`${e.name} · Flink ${e.flinkVersion||'-'} / CDC ${e.flinkCdcVersion||'-'}`" :value="e.id"/></el-select></label><label class="field-label">并行度<el-input-number v-model="form.parallelism" :min="1" :max="128" style="width:100%"/></label><label class="field-label">Checkpoint 间隔（秒）<el-input-number v-model="form.checkpointIntervalSec" :min="5" style="width:100%"/></label><label class="field-label">失败重试次数<el-input-number v-model="form.restartAttempts" :min="0" :max="100" style="width:100%"/></label></div></div>
        <div class="checkpoint-card"><div><strong>Checkpoint</strong><span>实时 CDC 的故障恢复依赖 Checkpoint；生产任务建议保持启用。</span></div><el-switch v-model="form.checkpointEnabled" active-text="启用" inactive-text="关闭"/></div>
        <div class="checkpoint-grid" v-if="form.checkpointEnabled"><div><span>间隔</span><strong>{{form.checkpointIntervalSec}} 秒</strong></div><div><span>超时</span><strong>{{form.checkpointTimeoutSec}} 秒</strong></div><div><span>失败容忍</span><strong>{{form.checkpointTolerance}} 次</strong></div><div><span>Externalized</span><strong>{{form.externalizedCheckpoint==='RETAIN'?'保留':'删除'}}</strong></div></div>
        <el-button link type="primary" @click="advancedRuntime=!advancedRuntime">{{advancedRuntime?'收起高级配置':'展开高级配置'}}</el-button>
        <div v-if="advancedRuntime" class="form-card advanced-card"><h5>高级配置</h5><div class="form-grid"><label class="field-label">JobManager Memory<el-input v-model="form.jmMemory"/></label><label class="field-label">TaskManager Memory<el-input v-model="form.tmMemory"/></label><label class="field-label">Task Slots<el-input-number v-model="form.taskSlots" :min="1" style="width:100%"/></label><label class="field-label">Restart Strategy<el-select v-model="form.restartStrategy" style="width:100%"><el-option label="固定延迟" value="FIXED_DELAY"/><el-option label="失败率" value="FAILURE_RATE"/><el-option label="不重启" value="NONE"/></el-select></label><label class="field-label">Checkpoint Timeout（秒）<el-input-number v-model="form.checkpointTimeoutSec" :min="30" style="width:100%"/></label><label class="field-label">Min Pause（秒）<el-input-number v-model="form.checkpointMinPauseSec" :min="0" style="width:100%"/></label><label class="field-label">并发 Checkpoint<el-input-number v-model="form.maxConcurrentCheckpoints" :min="1" :max="4" style="width:100%"/></label><label class="field-label">State Backend<el-select v-model="form.stateBackend" style="width:100%"><el-option label="RocksDB" value="rocksdb"/><el-option label="HashMap" value="hashmap"/></el-select></label><label class="field-label">Checkpoint Storage<el-input v-model="form.checkpointStorage" placeholder="由 Flink 环境统一配置时可留空"/></label><label class="field-label">Savepoint<el-input v-model="form.savepointPath" placeholder="可选"/></label></div><label class="field-label">高级 Flink 参数<el-input v-model="form.advancedParams" type="textarea" :rows="4" placeholder="仅平台运维人员使用；普通任务请留空"/></label></div>
      </section>

      <section v-else class="wizard-section confirm-section">
        <div class="section-head"><div><h4>确认创建</h4><p>创建前执行真实环境检查。Job Running 不等于数据正确，数据一致性在任务详情中持续校验。</p></div><el-button :loading="prechecking" @click="runPrecheck">重新检查</el-button></div>
        <div class="confirm-grid"><div><span>任务</span><strong>{{form.name}}</strong></div><div><span>同步链路</span><strong>{{sourceName(form.sourceDataSourceId)}} / {{form.sourceDatabase}} → {{sourceName(form.sinkDataSourceId)}} / {{form.sinkDatabase}}</strong></div><div><span>同步范围</span><strong>{{scopeLabel(form.syncScope)}} · {{selectedTables.length}} 张表</strong></div><div><span>启动模式</span><strong>{{startupLabel(form.startupMode)}}</strong></div><div><span>DELETE</span><strong>{{deleteLabel(form.deletePolicy)}}</strong></div><div><span>Flink</span><strong>{{envName(form.runtimeEnvironmentId)}} · 并行度 {{form.parallelism}}</strong></div></div>
        <div class="precheck-box"><div class="precheck-head"><strong>自动检查</strong><span>{{precheckItems.filter(x=>x.blocking).length}} 个阻断项，{{precheckItems.filter(x=>x.level==='WARNING').length}} 个提醒</span></div><div v-if="!precheckItems.length" class="empty-check">尚未获得检查结果</div><div v-for="item in precheckItems" :key="`${item.code}-${item.detail}`" :class="['check-row',item.level.toLowerCase()]"><span class="check-icon">{{item.blocking?'×':item.level==='WARNING'?'!':'✓'}}</span><strong>{{item.message}}</strong><span>{{item.detail}}</span></div></div>
        <details class="yaml-preview"><summary>查看平台生成的 Flink CDC Pipeline</summary><pre>{{yamlPreview||'预检后展示，密码会自动脱敏。'}}</pre></details>
      </section>
    </div>
    <template #footer><div class="wizard-footer"><el-button @click="editorVisible=false">取消</el-button><div class="ds-spacer"/><el-button v-if="editorStep>0" @click="prevStep">上一步</el-button><el-button v-if="editorStep<4" type="primary" @click="nextStep">下一步</el-button><el-button v-else type="primary" :loading="saving" @click="finalSave">{{editing?'保存修改':'创建任务'}}</el-button></div></template>
  </el-drawer>

  <el-drawer v-model="detailVisible" size="78%" destroy-on-close class="detail-drawer" @closed="closeDetail">
    <template #header><div class="detail-head"><div><div class="eyebrow">实时同步任务</div><h3>{{detailJob?.name||'任务详情'}}</h3><p>{{sourceName((detailJob?.spec as any)?.sourceDataSourceId)}} / {{(detailJob?.spec as any)?.sourceDatabase}} → {{sourceName((detailJob?.spec as any)?.sinkDataSourceId)}} / {{(detailJob?.spec as any)?.sinkDatabase}}</p></div><div class="detail-actions" v-if="activeDetailRow"><el-button @click="openEdit(activeDetailRow)">编辑</el-button><el-button v-if="activeDetailRow.releaseState!=='PUBLISHED'" type="primary" @click="publishRow(activeDetailRow)">发布</el-button><el-button v-else-if="activeDetailRow.observedState==='RUNNING'" type="warning" @click="stop(activeDetailRow)">停止</el-button><el-button v-else type="success" @click="start(activeDetailRow)">启动</el-button><el-button v-if="activeDetailRow.releaseState==='PUBLISHED'&&activeDetailRow.observedState==='RUNNING'" type="primary" @click="restart(activeDetailRow)">重启</el-button></div></div></template>
    <div v-loading="detailLoading" v-if="detailJob" class="detail-body">
      <div class="detail-summary"><div><span>运行状态</span><StatusBadge :status="detailRuntime?.job?.observedState||detailJob.observedState"/></div><div><span>发布状态</span><StatusBadge :status="detailJob.releaseState"/></div><div><span>Flink JobId</span><strong class="mono">{{detailRuntime?.execution?.engineJobId||'—'}}</strong></div><div><span>Flink 环境</span><strong>{{detailRuntime?.environment?.name||envName(detailJob.runtimeEnvironmentId)}}</strong></div><div><span>同步表</span><strong>{{(detailJob.spec as any)?.tables?.length||0}} 张</strong></div><div><span>负责人</span><strong>{{detailJob.createdBy}}</strong></div></div>
      <el-tabs v-model="detailTab" @tab-change="detailTabChanged" class="detail-tabs">
        <el-tab-pane label="概览" name="overview"><div class="overview-grid"><div class="metric-box"><span>Source Records/s</span><strong>{{vertexMetric('0.numRecordsOut')??'未采集'}}</strong></div><div class="metric-box"><span>Sink Records/s</span><strong>{{vertexMetric('0.numRecordsIn')??'未采集'}}</strong></div><div class="metric-box"><span>当前延迟</span><strong>{{activeDetailRow?.lagMs==null?'未采集':`${(activeDetailRow.lagMs/1000).toFixed(1)}s`}}</strong></div><div class="metric-box"><span>Checkpoint</span><strong>{{activeDetailRow?.checkpointStatus==='COMPLETED'?'正常':'未采集'}}</strong></div></div><div class="detail-card"><h4>任务信息</h4><el-descriptions :column="3" border><el-descriptions-item label="启动模式">{{startupLabel((detailJob.spec as any).startupMode||'initial')}}</el-descriptions-item><el-descriptions-item label="DELETE">{{deleteLabel((detailJob.spec as any).deletePolicy||'SYNC_DELETE')}}</el-descriptions-item><el-descriptions-item label="Schema Evolution">{{(detailJob.spec as any).schemaEvolution||'EXCEPTION'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{formatDateTime(detailJob.createdAt)}}</el-descriptions-item><el-descriptions-item label="更新时间">{{formatDateTime(detailJob.updatedAt)}}</el-descriptions-item><el-descriptions-item label="最近异常">{{detailJob.lastError||'无'}}</el-descriptions-item></el-descriptions></div></el-tab-pane>
        <el-tab-pane label="同步配置" name="config"><div class="detail-card"><h4>业务同步规则</h4><el-descriptions :column="3" border><el-descriptions-item label="来源">{{sourceName((detailJob.spec as any).sourceDataSourceId)}} / {{(detailJob.spec as any).sourceDatabase}}</el-descriptions-item><el-descriptions-item label="目标">{{sourceName((detailJob.spec as any).sinkDataSourceId)}} / {{(detailJob.spec as any).sinkDatabase}}</el-descriptions-item><el-descriptions-item label="同步范围">{{scopeLabel((detailJob.spec as any).syncScope)}}</el-descriptions-item><el-descriptions-item label="启动模式">{{startupLabel((detailJob.spec as any).startupMode||'initial')}}</el-descriptions-item><el-descriptions-item label="DELETE 策略">{{deleteLabel((detailJob.spec as any).deletePolicy||'SYNC_DELETE')}}</el-descriptions-item><el-descriptions-item label="并行度">{{(detailJob.spec as any).parallelism||1}}</el-descriptions-item></el-descriptions><el-table :data="(detailJob.spec as any).tables||[]" size="small" class="detail-table"><el-table-column prop="sourceTable" label="源表"/><el-table-column prop="targetTable" label="目标表"/></el-table></div></el-tab-pane>
        <el-tab-pane label="运行监控" name="monitor"><div class="overview-grid"><div class="metric-box"><span>Source Records/s</span><strong>{{vertexMetric('0.numRecordsOut')??'未采集'}}</strong></div><div class="metric-box"><span>Sink Records/s</span><strong>{{vertexMetric('0.numRecordsIn')??'未采集'}}</strong></div><div class="metric-box"><span>Backpressure ms/s</span><strong>{{vertexMetric('0.backPressuredTimeMsPerSecond')??'未采集'}}</strong></div><div class="metric-box"><span>Checkpoint Duration</span><strong>{{metricValue('lastCheckpointDuration')??'未采集'}}</strong></div><div class="metric-box"><span>Restart Count</span><strong>{{metricValue('numRestarts')??'未采集'}}</strong></div><div class="metric-box"><span>Checkpoint Failure</span><strong>{{metricValue('numberOfFailedCheckpoints')??'未采集'}}</strong></div><div class="metric-box"><span>TaskManager 数量</span><strong>{{taskManagerCount()??'未采集'}}</strong></div><div class="metric-box"><span>运行时长</span><strong>{{metricValue('uptime')?fmtDuration(metricValue('uptime')):'未采集'}}</strong></div></div><div class="runtime-note">指标直接读取 Flink REST；当前 Connector 未暴露可靠 Lag 指标时显示“未采集”，不会用模拟值代替。</div></el-tab-pane>
        <el-tab-pane label="Checkpoint" name="checkpoint"><div class="detail-card"><div class="card-head"><h4>Checkpoint 历史</h4><el-button @click="loadDetailTab('checkpoint')">刷新</el-button></div><el-table :data="checkpointRows" size="small"><el-table-column prop="checkpointId" label="Checkpoint ID"/><el-table-column label="状态"><template #default="s"><StatusBadge :status="s.row.status"/></template></el-table-column><el-table-column label="耗时"><template #default="s">{{fmtDuration(s.row.durationMs)}}</template></el-table-column><el-table-column label="State Size"><template #default="s">{{fmtBytes(s.row.stateSizeBytes)}}</template></el-table-column><el-table-column label="完成时间"><template #default="s">{{formatDateTime(s.row.completedAt)}}</template></el-table-column></el-table></div></el-tab-pane>
        <el-tab-pane label="日志" name="logs"><div class="detail-card"><div class="card-head"><h4>Flink 异常 / 日志</h4><el-button @click="loadDetailTab('logs')">刷新</el-button></div><pre class="log-viewer">{{logText()}}</pre></div></el-tab-pane>
        <el-tab-pane label="Schema 变更" name="schema"><div class="detail-card"><div class="card-head"><div><h4>Schema 变更记录</h4><p>通过源表 Schema 快照检测新增、删除、类型变化；疑似重命名默认要求人工确认。</p></div><el-button @click="scanSchema">检测变更</el-button></div><div v-if="!schemaChanges.length" class="empty-panel">当前没有平台记录到的 Schema 变更。首次检测会建立基线快照，不会把现有字段误判为新增。</div><el-table v-else :data="schemaChanges" size="small"><el-table-column label="发生时间" min-width="170"><template #default="s">{{formatDateTime(s.row.occurredAt)}}</template></el-table-column><el-table-column prop="sourceTable" label="源表"/><el-table-column prop="changeType" label="变更类型"/><el-table-column prop="ddlText" label="DDL" min-width="260" show-overflow-tooltip/><el-table-column prop="policyAction" label="平台处理"/><el-table-column prop="targetResult" label="目标结果"/><el-table-column label="状态"><template #default="s"><StatusBadge :status="s.row.status"/></template></el-table-column></el-table></div></el-tab-pane>
        <el-tab-pane label="数据校验" name="validation"><div class="detail-card"><div class="card-head"><div><h4>数据正确性校验</h4><p>Job Running ≠ 数据一定正确。按需检查源/目标行数、主键、类型/时区和 DELETE 策略。</p></div><el-button type="primary" @click="runDataValidation">立即校验</el-button></div><el-table :data="validationRows" size="small"><el-table-column label="检查时间" min-width="170"><template #default="s">{{formatDateTime(s.row.checkedAt)}}</template></el-table-column><el-table-column prop="validationType" label="检查项" min-width="150"/><el-table-column prop="sourceTable" label="源表" min-width="140"/><el-table-column prop="sourceValue" label="源端"/><el-table-column prop="targetValue" label="目标端"/><el-table-column label="状态" width="100"><template #default="s"><StatusBadge :status="s.row.status"/></template></el-table-column><el-table-column prop="detail" label="说明" min-width="260" show-overflow-tooltip/></el-table></div></el-tab-pane>
        <el-tab-pane label="运行历史" name="history"><div class="detail-card"><h4>执行记录</h4><el-table :data="executions" size="small"><el-table-column prop="definitionVersion" label="版本" width="80"/><el-table-column prop="engineJobId" label="Flink JobId" min-width="260" show-overflow-tooltip/><el-table-column label="状态"><template #default="s"><StatusBadge :status="s.row.status"/></template></el-table-column><el-table-column label="开始时间" min-width="170"><template #default="s">{{formatDateTime(s.row.startedAt||s.row.createdAt)}}</template></el-table-column><el-table-column label="结束时间" min-width="170"><template #default="s">{{formatDateTime(s.row.finishedAt)}}</template></el-table-column><el-table-column prop="errorMessage" label="异常" min-width="260" show-overflow-tooltip/></el-table><h4 class="event-title">生命周期事件</h4><el-table :data="events" size="small"><el-table-column label="时间" min-width="170"><template #default="s">{{formatDateTime(s.row.createdAt)}}</template></el-table-column><el-table-column prop="eventType" label="事件" min-width="140"/><el-table-column prop="detail" label="详情" min-width="360" show-overflow-tooltip/></el-table></div></el-tab-pane>
      </el-tabs>
    </div>
  </el-drawer>
</div>
</template>

